/* ===================== ADMIN SHELL ===================== */
function adminNavItems(){
  return [
    {view:'admin-overview', icon:'space_dashboard', label:t('navOverview')},
    {view:'admin-properties', icon:'apartment', label:t('navProperties')},
    {view:'admin-inspectors', icon:'badge', label:t('navInspectors')},
    {view:'admin-assignments', icon:'assignment_turned_in', label:t('navAssignments')},
    {view:'admin-inspections', icon:'fact_check', label:t('navInspections')},
    {view:'admin-standards', icon:'menu_book', label:t('navStandards')},
    {view:'admin-documents', icon:'request_quote', label:t('navDocuments')},
    {view:'admin-settings', icon:'settings', label:t('navSettings')}
  ];
}
function adminPageTitle(){
  const item = adminNavItems().find(n=>n.view===state.view);
  if(item) return item.label;
  if(state.view==='admin-report') return t('detailTitle');
  return '';
}
function renderAdminShell(contentHtml){
  const user = currentUser();
  const nav = adminNavItems().map(n=>`
    <button class="side-link ${state.view===n.view?'active':''}" onclick="go('${n.view}')">${ic(n.icon)}<span>${n.label}</span></button>
  `).join('');
  return `
  <div class="admin-shell">
    <div class="sidebar-backdrop ${state.sidebarOpen?'show':''}" onclick="toggleSidebar()"></div>
    <aside class="admin-sidebar ${state.sidebarOpen?'open':''}">
      <div class="side-brand"><img src="data:image/png;base64," alt="THO"></div>
      <nav class="side-nav">
        <div class="side-section">${t('adminPanel')}</div>
        ${nav}
      </nav>
      <div class="side-foot">
        <div class="side-user" onclick="openDrawer('profile')" title="${t('editProfileTitle')}" style="cursor:pointer;">
          <div class="avatar">${initials(user.name)}</div>
          <div><div class="su-name">${esc(tl(user.name))}</div><div class="su-role">${esc(tl(user.title))}</div></div>
          <span class="side-user-edit-ic">${ic('edit')}</span>
        </div>
        <button class="btn btn-outline btn-sm btn-block side-logout" onclick="logout()">${ic('logout')}${t('logout')}</button>
      </div>
    </aside>
    <div class="admin-main">
      <div class="admin-topbar">
        <h1><button class="hamburger" onclick="toggleSidebar()">${ic('menu')}</button>${esc(adminPageTitle())}</h1>
        <div class="tb-actions">
          <button class="lang-toggle" onclick="toggleLang()">${ic('translate')}<span>${state.lang==='ar'?'English':'عربي'}</span></button>
        </div>
      </div>
      <div class="admin-content">${contentHtml}</div>
    </div>
  </div>
  ${renderDrawer()}
  ${renderAdminSigModal()}
  `;
}

/* ---- Admin: Overview ---- */
function renderAdminOverview(){
  const completed = state.inspections.filter(i=>i.status==='completed');
  const avg = completed.length ? Math.round(completed.reduce((s,i)=> s + (i.overall||0),0)/completed.length) : 0;
  const openAssignments = state.assignments.filter(a=>a.status!=='completed').length;
  const overdueCount = state.assignments.filter(isOverdue).length;
  const inspectorCount = USERS.filter(u=>u.role==='inspector').length;

  const recent = state.assignments.slice().sort((a,b)=>b.createdAt-a.createdAt).slice(0,8);
  const rows = recent.map(as=>{
    const hotel = hotelById(as.hotelId); const insp = userById(as.inspectorId);
    return `<tr>
      <td><strong>${esc(tl(hotel && hotel.name))}</strong></td>
      <td>${esc(tl(insp && insp.name))}</td>
      <td>${esc(as.dueDate)}</td>
      <td>${priorityBadge(as.priority)}</td>
      <td>${assignmentStatusBadge(as)}</td>
      <td style="text-align:end;">${as.inspectionId ? `<button class="btn btn-ghost btn-sm" onclick="viewAdminReport('${as.inspectionId}')">${t('view')}</button>` : ''}</td>
    </tr>`;
  }).join('');

  return `
  <div class="page-head"><div><h2>${t('overviewTitle')}</h2><p>${t('overviewSub')}</p></div>
    <button class="btn btn-gold" onclick="openDrawer('assignment')">${ic('add')}${t('newAssignment')}</button>
  </div>
  <div class="stat-row">
    <div class="stat"><div class="stat-ic">${ic('apartment')}</div><div><div class="num">${state.hotels.length}</div><div class="lbl">${t('kpiProperties')}</div></div></div>
    <div class="stat"><div class="stat-ic">${ic('badge')}</div><div><div class="num">${inspectorCount}</div><div class="lbl">${t('kpiInspectors')}</div></div></div>
    <div class="stat"><div class="stat-ic">${ic('assignment_turned_in')}</div><div><div class="num">${openAssignments}</div><div class="lbl">${t('kpiAssignments')}</div></div></div>
    <div class="stat"><div class="stat-ic" style="${overdueCount>0?'background:var(--red-bg);color:var(--red);':''}">${ic('schedule')}</div><div><div class="num" style="color:${overdueCount>0?'var(--red)':'var(--navy)'}">${overdueCount}</div><div class="lbl">${t('kpiOverdue')}</div></div></div>
  </div>
  <div class="stat-row" style="grid-template-columns:1fr 1fr;">
    <div class="stat"><div class="stat-ic">${ic('fact_check')}</div><div><div class="num">${state.inspections.length}</div><div class="lbl">${t('totalInspections')}</div></div></div>
    <div class="stat"><div class="stat-ic">${ic('percent')}</div><div><div class="num">${avg}%</div><div class="lbl">${t('avgScore')}</div></div></div>
  </div>
  <div class="card">
    <h3 style="margin-top:0;">${t('recentActivity')}</h3>
    ${recent.length===0 ? `<div class="empty"><div class="big">${ic('assignment_turned_in')}</div>${t('noAssignments')}</div>` : `
    <table><thead><tr><th>${t('colProperty')}</th><th>${t('colInspector')}</th><th>${t('colDue')}</th><th>${t('colPriority')}</th><th>${t('colStatus')}</th><th></th></tr></thead><tbody>${rows}</tbody></table>`}
  </div>
  `;
}

/* ---- Admin: Properties ---- */
function renderAdminProperties(){
  const rows = state.hotels.map(h=>{
    const typeLabel = PROPERTY_TYPES[h.type] ? tl(PROPERTY_TYPES[h.type]) : '';
    return `<tr>
      <td class="name-cell">${h.logo ? `<img class="hotel-logo-thumb" src="${esc(h.logo)}" alt="">` : `<div class="avatar avatar-sm" style="background:var(--navy);color:#fff;">${ic('apartment')}</div>`}<strong>${esc(tl(h.name))}</strong></td>
      <td>${esc(typeLabel)}</td>
      <td>${esc(tl(h.city))}</td>
      <td>${esc(h.contact||'')}<br><span style="color:var(--muted);font-size:12px;">${esc(h.phone||'')}</span></td>
      <td class="row-actions">
        <button class="icon-btn" onclick="openDrawer('property','${h.id}')" title="${t('edit')}" aria-label="${t('edit')}">${ic('edit')}</button>
        <button class="icon-btn" onclick="toggleHotelAccountPanel('${h.id}')" title="${t('hotelAccountTitle')}" aria-label="${t('hotelAccountTitle')}">${ic('key')}</button>
        <button class="icon-btn" onclick="uploadHotelLogo('${h.id}')" title="${t('uploadLogo')}" aria-label="${t('uploadLogo')}">${ic('image')}</button>
        ${h.logo ? `<button class="icon-btn" onclick="removeHotelLogo('${h.id}')" title="${t('removeLogo')}" aria-label="${t('removeLogo')}">${ic('hide_image')}</button>` : ''}
        <button class="icon-btn danger" onclick="deleteHotel('${h.id}')" title="${t('delete')}" aria-label="${t('delete')}">${ic('delete')}</button>
      </td>
    </tr>
    ${state.openHotelAccountId===h.id ? `<tr><td colspan="5" style="padding:0;border:none;"><div class="hotel-account-box">${renderHotelAccountPanel(h)}</div></td></tr>` : ''}`;
  }).join('');
  return `
  <div class="page-head"><div><h2>${t('propertiesTitle')}</h2><p>${t('propertiesSub')}</p></div>
    <button class="btn btn-gold" onclick="openDrawer('property')">${ic('add')}${t('addProperty')}</button>
  </div>
  <div class="card">
    ${state.hotels.length===0 ? `<div class="empty"><div class="big">${ic('apartment')}</div>${t('noProperties')}</div>` : `
    <table><thead><tr><th>${t('colProperty')}</th><th>${t('colType')}</th><th>${t('colCity')}</th><th>${t('colContact')}</th><th></th></tr></thead><tbody>${rows}</tbody></table>`}
  </div>
  `;
}
function renderHotelAccountPanel(h){
  const account = state.hotelAccounts[h.id];
  const reveal = state.hotelAccountReveal && state.hotelAccountReveal.hotelId===h.id ? state.hotelAccountReveal : null;
  const revealHtml = reveal ? `
    <div class="hotel-account-creds">
      <div class="cred-row"><span>${t('hotelAccountUsername')}</span><b>${esc(reveal.username)}</b></div>
      <div class="cred-row"><span>${t('hotelAccountTempPassword')}</span><b>${esc(reveal.tempPassword)}</b></div>
    </div>
    <p style="font-size:12px;color:var(--muted);margin:8px 0 0;">${esc(t('hotelAccountHint'))}</p>
  ` : '';
  if(!account){
    return `
    <div><strong>${esc(t('hotelAccountTitle'))}</strong> — <span style="color:var(--muted);">${esc(t('hotelAccountNone'))}</span></div>
    <button class="btn btn-gold btn-sm" style="margin-top:10px;" onclick="createHotelAccount('${h.id}')">${ic('vpn_key')}${t('createHotelAccount')}</button>
    ${revealHtml}
    `;
  }
  return `
  <div><strong>${esc(t('hotelAccountTitle'))}</strong> — <code>${esc(account.username)}</code></div>
  <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap;">
    <button class="btn btn-outline btn-sm" onclick="resetHotelAccountPassword('${h.id}')">${ic('lock_reset')}${t('resetHotelPassword')}</button>
    <button class="btn btn-outline btn-sm" style="color:var(--red);border-color:var(--red);" onclick="deleteHotelAccount('${h.id}')">${ic('delete')}${t('deleteHotelAccount')}</button>
  </div>
  ${revealHtml}
  `;
}
function toggleHotelAccountPanel(hotelId){
  state.openHotelAccountId = state.openHotelAccountId===hotelId ? null : hotelId;
  state.hotelAccountReveal = null;
  render();
}
async function createHotelAccount(hotelId){
  let result;
  try{
    result = await apiPost('/hotels/' + hotelId + '/account', {});
  }catch(e){
    alert((state.lang==='ar' ? 'تعذّر إنشاء الحساب: ' : 'Could not create account: ') + e.message);
    return;
  }
  state.hotelAccounts[hotelId] = { id: result.id, username: result.username, name: result.name };
  state.hotelAccountReveal = { hotelId, username: result.username, tempPassword: result.tempPassword };
  render();
}
async function resetHotelAccountPassword(hotelId){
  let result;
  try{
    result = await apiPost('/hotels/' + hotelId + '/account/reset-password', {});
  }catch(e){
    alert((state.lang==='ar' ? 'تعذّر إعادة تعيين كلمة المرور: ' : 'Could not reset password: ') + e.message);
    return;
  }
  const account = state.hotelAccounts[hotelId];
  state.hotelAccountReveal = { hotelId, username: account ? account.username : '', tempPassword: result.tempPassword };
  render();
}
async function deleteHotelAccount(hotelId){
  if(!confirm(t('confirmDeleteHotelAccount'))) return;
  try{ await apiDelete('/hotels/' + hotelId + '/account'); }catch(e){
    alert((state.lang==='ar' ? 'تعذّر حذف الحساب: ' : 'Could not delete account: ') + e.message);
    return;
  }
  delete state.hotelAccounts[hotelId];
  state.hotelAccountReveal = null;
  render();
}

/* ---- Admin: Inspectors ---- */
function renderAdminInspectors(){
  const inspectors = USERS.filter(u=>u.role==='inspector');
  const rows = inspectors.map(u=>{
    const count = state.assignments.filter(a=>a.inspectorId===u.id && a.status!=='completed').length;
    return `<tr>
      <td class="name-cell"><div class="avatar avatar-sm">${initials(u.name)}</div><div><strong>${esc(tl(u.name))}</strong><div style="color:var(--muted);font-size:12px;">${esc(tl(u.title))}</div></div></td>
      <td>${esc(u.username)}</td>
      <td><span class="badge badge-gold">${count} ${t('inspAssignedCount')}</span></td>
      <td class="row-actions">
        <button class="icon-btn" onclick="openDrawer('inspector','${u.id}')" title="${t('edit')}" aria-label="${t('edit')}">${ic('edit')}</button>
        <button class="icon-btn" onclick="resetInspectorPassword('${u.id}')" title="${t('resetPasswordBtn')}" aria-label="${t('resetPasswordBtn')}">${ic('lock_reset')}</button>
        <button class="icon-btn danger" onclick="deleteInspector('${u.id}')" title="${t('delete')}" aria-label="${t('delete')}">${ic('delete')}</button>
      </td>
    </tr>`;
  }).join('');
  return `
  <div class="page-head"><div><h2>${t('inspectorsTitle')}</h2><p>${t('inspectorsSub')}</p></div>
    <button class="btn btn-gold" onclick="openDrawer('inspector')">${ic('add')}${t('addInspector')}</button>
  </div>
  <div class="card">
    ${inspectors.length===0 ? `<div class="empty"><div class="big">${ic('badge')}</div>${t('noInspectors')}</div>` : `
    <table><thead><tr><th>${t('colInspector')}</th><th>${t('colUsername')}</th><th>${t('kpiAssignments')}</th><th></th></tr></thead><tbody>${rows}</tbody></table>`}
  </div>
  `;
}

/* ---- Admin: Assignments ---- */
function renderAdminAssignments(){
  const list = state.assignments.slice().sort((a,b)=>b.createdAt-a.createdAt);
  const rows = list.map(as=>{
    const hotel = hotelById(as.hotelId); const insp = userById(as.inspectorId);
    return `<tr>
      <td><strong>${esc(tl(hotel && hotel.name))}</strong><div style="color:var(--muted);font-size:12px;">${esc(tl(hotel && hotel.city))}</div></td>
      <td class="name-cell"><div class="avatar avatar-sm">${initials(insp && insp.name)}</div>${esc(tl(insp && insp.name))}</td>
      <td>${esc(as.dueDate)}</td>
      <td>${standardBadge(as.standardId || 'audit4')}</td>
      <td>${priorityBadge(as.priority)}</td>
      <td>${assignmentStatusBadge(as)}</td>
      <td class="row-actions">
        ${as.inspectionId ? `<button class="icon-btn" onclick="viewAdminReport('${as.inspectionId}')" title="${t('view')}" aria-label="${t('view')}">${ic('visibility')}</button>` : ''}
        <button class="icon-btn" onclick="openDrawer('assignment','${as.id}')" title="${t('edit')}" aria-label="${t('edit')}">${ic('edit')}</button>
        <button class="icon-btn danger" onclick="deleteAssignment('${as.id}')" title="${t('delete')}" aria-label="${t('delete')}">${ic('delete')}</button>
      </td>
    </tr>`;
  }).join('');
  return `
  <div class="page-head"><div><h2>${t('assignmentsTitle')}</h2><p>${t('assignmentsSub')}</p></div>
    <button class="btn btn-gold" onclick="openDrawer('assignment')">${ic('add')}${t('newAssignment')}</button>
  </div>
  <div class="card">
    ${list.length===0 ? `<div class="empty"><div class="big">${ic('assignment_turned_in')}</div>${t('noAssignments')}</div>` : `
    <table><thead><tr><th>${t('colProperty')}</th><th>${t('colInspector')}</th><th>${t('colDue')}</th><th>${t('colStandard')}</th><th>${t('colPriority')}</th><th>${t('colStatus')}</th><th></th></tr></thead><tbody>${rows}</tbody></table>`}
  </div>
  `;
}

/* ---- Admin: All Inspections ---- */
function renderAdminInspections(){
  const list = state.inspections.slice().sort((a,b)=>b.createdAt-a.createdAt);
  let filtered = list;
  if(state.inspFilterStatus==='completed') filtered = list.filter(i=>i.status==='completed');
  else if(state.inspFilterStatus==='in_progress') filtered = list.filter(i=>i.status!=='completed');

  const rows = filtered.map(insp=>{
    const overall = insp.overall || 0;
    const badge = insp.status==='completed'
      ? `<span class="badge ${overall>=75?'badge-green':(overall>=60?'badge-amber':'badge-red')}">${overall}%</span>`
      : `<span class="badge badge-amber">${t('statusProgress')}</span>`;
    return `<tr>
      <td><strong>${esc(inspPropertyName(insp))}</strong></td>
      <td>${esc(insp.propertyTypeLabel||'')}</td>
      <td>${esc(inspInspectorName(insp))}</td>
      <td>${esc(insp.visitDate||'')}</td>
      <td>${badge}</td>
      <td>${insp.status==='completed' ? `<span class="badge badge-gray">${t('statusDone')}</span>` : `<span class="badge badge-amber">${t('statusProgress')}</span>`}</td>
      <td class="row-actions" style="justify-content:flex-end;">
        <button class="btn btn-ghost btn-sm" onclick="viewAdminReport('${insp.id}')">${t('view')}</button>
        <button class="icon-btn danger" onclick="deleteInspectionReport('${insp.id}')" title="${t('delete')}" aria-label="${t('delete')}">${ic('delete')}</button>
      </td>
    </tr>`;
  }).join('');

  return `
  <div class="page-head"><div><h2>${t('allInspectionsTitle')}</h2><p>${t('allInspectionsSub')}</p></div></div>
  <div class="toolbar">
    <select class="mini" onchange="state.inspFilterStatus=this.value;render();">
      <option value="all" ${state.inspFilterStatus==='all'?'selected':''}>${t('filterAllStatus')}</option>
      <option value="completed" ${state.inspFilterStatus==='completed'?'selected':''}>${t('statusDone')}</option>
      <option value="in_progress" ${state.inspFilterStatus==='in_progress'?'selected':''}>${t('statusProgress')}</option>
    </select>
  </div>
  <div class="card">
    ${filtered.length===0 ? `<div class="empty"><div class="big">${ic('fact_check')}</div>${t('noInspectionsAdmin')}</div>` : `
    <table><thead><tr><th>${t('colProperty')}</th><th>${t('colType')}</th><th>${t('colInspector')}</th><th>${t('colDate')}</th><th>${t('colScore')}</th><th>${t('colStatus')}</th><th></th></tr></thead><tbody>${rows}</tbody></table>`}
  </div>
  `;
}
/* ---- Admin: Settings ---- */
function fmtDate(ms){ return ms ? new Date(ms).toLocaleDateString(state.lang==='ar'?'ar-EG':'en-GB') : ''; }
function renderTemplateSlot(type, tpl){
  const label = type==='proposal' ? t('settingsProposalTemplate') : t('settingsContractTemplate');
  return `
  <div class="field">
    <label>${label}</label>
    <div class="tpl-slot">
      ${tpl ? `<div class="tpl-file">${ic('description')}<div><strong>${esc(tpl.originalName)}</strong><div class="hint">${t('settingsTemplateUploaded')} ${fmtDate(tpl.uploadedAt)}</div></div></div>`
        : `<div class="hint">${t('settingsNoTemplate')}</div>`}
      <label class="btn btn-outline btn-sm" style="cursor:pointer;margin-top:10px;">${ic('upload')}${tpl?t('settingsReplaceTemplate'):t('settingsUploadTemplate')}<input type="file" accept=".docx" style="display:none;" onchange="uploadTemplate('${type}', this)"></label>
    </div>
  </div>`;
}
function renderAdminSettings(){
  const s = state.settings || {companyName:{en:'',ar:''}, logo:'', email:'', phone:'', website:'', address:''};
  const tpl = state.templates || {};
  return `
  <div class="page-head"><div><h2>${t('navSettings')}</h2></div></div>

  <div class="card" style="margin-bottom:20px;">
    <h3 style="margin-top:0;">${t('settingsCompanyTitle')}</h3>
    <p class="hint" style="margin-bottom:16px;">${t('settingsCompanyDesc')}</p>
    <div class="form-grid">
      <div class="field"><label for="sf_name_en">${t('settingsNameEn')}</label><input id="sf_name_en" value="${esc(s.companyName.en)}"></div>
      <div class="field"><label for="sf_name_ar">${t('settingsNameAr')}</label><input id="sf_name_ar" value="${esc(s.companyName.ar)}"></div>
      <div class="field"><label for="sf_email">${t('settingsEmail')}</label><input id="sf_email" dir="ltr" style="text-align:left;" value="${esc(s.email)}"></div>
      <div class="field"><label for="sf_phone">${t('settingsPhone')}</label><input id="sf_phone" dir="ltr" style="text-align:left;" value="${esc(s.phone)}"></div>
      <div class="field"><label for="sf_website">${t('settingsWebsite')}</label><input id="sf_website" dir="ltr" style="text-align:left;" value="${esc(s.website)}"></div>
      <div class="field"><label for="sf_address">${t('settingsAddress')}</label><input id="sf_address" value="${esc(s.address)}"></div>
    </div>
    <div class="field" style="max-width:360px;">
      <label>${t('settingsLogo')}</label>
      <div style="display:flex;align-items:center;gap:14px;">
        <div class="logo-preview">${s.logo ? `<img src="${esc(s.logo)}" alt="logo">` : ic('image')}</div>
        <label class="btn btn-outline btn-sm" style="cursor:pointer;">${ic('upload')}${t('settingsUploadLogo')}<input type="file" accept="image/*" style="display:none;" onchange="pickLogoFile(this)"></label>
      </div>
    </div>
    <div class="drawer-foot" style="border:none;padding:18px 0 0;justify-content:flex-start;">
      <button class="btn btn-primary" onclick="saveSettings()">${ic('check')}${t('settingsSave')}</button>
    </div>
  </div>

  <div class="card">
    <h3 style="margin-top:0;">${t('settingsTemplatesTitle')}</h3>
    <p class="hint" style="margin-bottom:16px;">${t('settingsTemplatesDesc')}</p>
    <div class="form-grid">
      ${renderTemplateSlot('proposal', tpl.proposal)}
      ${renderTemplateSlot('contract', tpl.contract)}
    </div>
    <h4>${t('settingsPlaceholdersTitle')}</h4>
    <div class="placeholder-grid">
      ${PLACEHOLDER_TAGS.map(p=>`<div class="ph-chip"><code>{{${p.key}}}</code><span>${esc(state.lang==='ar'?p.ar:p.en)}</span></div>`).join('')}
    </div>
  </div>
  `;
}
function pickLogoFile(input){
  const file = input.files && input.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = ()=>{
    pendingLogoDataUrl = reader.result;
    state.settings = state.settings || {companyName:{en:'',ar:''}};
    state.settings.logo = pendingLogoDataUrl;
    render();
  };
  reader.readAsDataURL(file);
}
async function saveSettings(){
  const body = {
    name_en: document.getElementById('sf_name_en').value.trim(),
    name_ar: document.getElementById('sf_name_ar').value.trim(),
    email: document.getElementById('sf_email').value.trim(),
    phone: document.getElementById('sf_phone').value.trim(),
    website: document.getElementById('sf_website').value.trim(),
    address: document.getElementById('sf_address').value.trim()
  };
  if(pendingLogoDataUrl !== undefined) body.logo = pendingLogoDataUrl;
  try{
    state.settings = await apiPut('/settings', body);
    pendingLogoDataUrl = undefined;
    alert(t('settingsSaved'));
    render();
  }catch(e){
    alert((state.lang==='ar'?'حدث خطأ: ':'Something went wrong: ') + e.message);
  }
}
async function uploadTemplate(type, input){
  const file = input.files && input.files[0];
  if(!file) return;
  const fd = new FormData();
  fd.append('file', file);
  try{
    const res = await fetch('/api/templates/' + type, { method:'POST', body: fd, credentials:'same-origin' });
    const data = await res.json();
    if(!res.ok){
      if(data && data.error==='invalid_file_type'){
        const name = (data.detail && data.detail.originalname) || file.name;
        const msg = state.lang==='ar'
          ? `الملف "${name}" مش ملف .docx. لو ده ملف Word قديم بامتداد .doc، افتحه في Word واحفظه بصيغة .docx (من القائمة: حفظ باسم ← Word Document ‎(.docx)‎) وارفعه تاني.`
          : `The file "${name}" is not a .docx file. If this is an older .doc file, open it in Word and use "Save As" → "Word Document (.docx)", then upload the new file.`;
        alert(msg);
      } else if(data && data.error==='file_too_large'){
        alert(state.lang==='ar' ? 'الملف كبير أوي (الحد الأقصى 15 ميجا).' : 'The file is too large (15MB max).');
      } else {
        alert(t('settingsTemplateUploadFailed'));
      }
      input.value = '';
      return;
    }
    state.templates = await apiGet('/templates');
    render();
  }catch(e){
    alert(t('settingsTemplateUploadFailed'));
  }
  input.value = '';
}

/* ---- Admin: Proposals & Contracts (document generator) ---- */
