      <div><div class="hint">${t('settingsContractTemplate')}</div><strong style="color:${tpl.contract?'var(--green)':'var(--red)'};">${tpl.contract ? '✓ '+t('docsTemplateReady') : '✕ '+t('docsTemplateMissing')}</strong></div>
